// Shared by every script. The document arrives as a JSON string; patches are built up as plain objects.
const S = JSON.parse(state);
const E = S.packages.engine;
const T = E.utilities.time.properties.state;
const DT = Math.min(Math.max(T.delta, 0.001), 0.05);
const patch = {};
const X = {};   // what one section of the frame tells a later one, without going through the document
const node = path => {
	let n = patch;
	for (const k of path.split('.')) { n.packages = n.packages || {}; n = n.packages[k] = n.packages[k] || {}; }
	return n;
};
const put = (path, data) => {
	const n = node(path);
	n.properties = n.properties || {}; n.properties.meta = n.properties.meta || {};
	n.properties.meta.data = Object.assign(n.properties.meta.data || {}, data);
};
const comp = (path, name, data, content) => {
	const n = node(path);
	n.utilities = n.utilities || {};
	const u = n.utilities[name] = n.utilities[name] || {};
	if (data) { u.properties = u.properties || {}; u.properties.data = Object.assign(u.properties.data || {}, data); }
	if (content !== undefined) u.content = content;
};
const get = path => {
	let n = S;
	for (const k of path.split('.')) { n = n.packages && n.packages[k]; if (!n) return null; }
	return n;
};
const dat = path => { const n = get(path); return n && n.properties && n.properties.meta ? n.properties.meta.data : null; };
const done = () => Object.keys(patch).length ? JSON.stringify(patch) : undefined;

const len = v => Math.hypot(v[0], v[1], v[2]);
const sub = (a, b) => [a[0] - b[0], a[1] - b[1], a[2] - b[2]];
const add = (a, b) => [a[0] + b[0], a[1] + b[1], a[2] + b[2]];
const mul = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
const dot = (a, b) => a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
const norm = a => { const l = len(a) || 1; return [a[0] / l, a[1] / l, a[2] / l]; };
const clamp = (x, a, b) => Math.min(b, Math.max(a, x));
const wrap = a => { while (a > Math.PI) a -= 2 * Math.PI; while (a < -Math.PI) a += 2 * Math.PI; return a; };
const heading = (yaw, pitch) => [-Math.sin(yaw) * Math.cos(pitch), Math.sin(pitch), -Math.cos(yaw) * Math.cos(pitch)];
const hash = x => { const s = Math.sin(x * 12.9898 + 78.233) * 43758.5453; return s - Math.floor(s); };

// Applies a patch to this script's own copy of the document, so that a later section of the same script sees
// what an earlier one decided, exactly as a separate script would have, without a round trip through the engine.
const mergeInto = (target, patchObject) => {
	for (const k of Object.keys(patchObject)) {
		const v = patchObject[k];
		if (v === null) delete target[k];
		else if (v && typeof v === 'object' && !Array.isArray(v) && target[k] && typeof target[k] === 'object' && !Array.isArray(target[k])) mergeInto(target[k], v);
		else target[k] = (v && typeof v === 'object') ? JSON.parse(JSON.stringify(v)) : v;
	}
};

const CBOX = [[2,1,22,24],[2,0,22,23],[2,1,22,24],[2,0,22,23],[2,1,22,24],[2,0,22,23],[2,1,22,24],[2,0,22,23],[0,0,24,24],[2,1,22,24],[2,0,22,23],[3,3,21,21],[3,3,21,21],[6,5,17,20],[6,5,17,20],[4,6,19,24],[4,5,19,24],[5,7,20,24],[5,11,20,24],[5,10,20,24],[5,12,20,24],[0,3,24,24],[0,2,24,24],[0,4,24,24],[3,4,21,21],[0,8,24,20],[3,7,21,20]];
const THEMES = [{"sky":[0.7445,0.924,0.9158,1],"fill":[0.548,0.7742,0.8122,1],"far":[0.7445,0.924,0.9158,1],"seq":[8,9,10,11],"tint":[1,1,1,1]},{"sky":[0.9658,0.5924,0.2011,1],"fill":[0.6055,0.2233,0.1113,1],"far":[0.9658,0.5924,0.2011,1],"seq":[12,13],"tint":[1,1,1,1]},{"sky":[0.0432,0.175,0.0768,1],"fill":[0.0046,0.0885,0.0454,1],"far":[0.0432,0.175,0.0768,1],"seq":[14,15],"tint":[0.35,0.5,0.42,1]}];
const TILE_IDS = [6,10,21,22,23,26,33,42,43,53,61,62,63,68,80,81,82,83,85,86,101,102,103,105,107,121,122,123,125,126,127,129,131,142,153,154,155];
// What the game is made of: the pictures (three sheets of equal squares), how terrain picks its tiles, and the levels.
// Units are tiles: one tile (18 pixels of the sheet) is one unit of the world, x to the right and y up.

const SHEETS = {
	t: { file: 'Assets/Sprites/tiles.png', w: 360, h: 162, p: 18, cols: 20 },
	c: { file: 'Assets/Sprites/characters.png', w: 216, h: 72, p: 24, cols: 9 },
	b: { file: 'Assets/Sprites/backgrounds.png', w: 192, h: 72, p: 24, cols: 8 }
};
// [u, v, width, height] of square i of a sheet, with the edges taken in by a fifth of a pixel so that nearest-neighbour sampling never reaches the next square
const regionOf = (sheet, i) => {
	const S = SHEETS[sheet], col = i % S.cols, row = Math.floor(i / S.cols), e = 0.2;
	return [+((col * S.p + e) / S.w).toFixed(5), +(1 - ((row + 1) * S.p - e) / S.h).toFixed(5), +((S.p - 2 * e) / S.w).toFixed(5), +((S.p - 2 * e) / S.h).toFixed(5)];
};
const CELL = 24 / 18;   // a character's square, in tiles

// ---- terrain: three kinds of top (grass, sand, snow) over one kind of earth. A tile is chosen by what is around it.
const TOPS = { G: [0, 20], S: [40, 60], N: [80, 100] };   // [a thin slab, the top of something tall], each four wide: single, left, middle, right
const isTerrain = c => c === 'G' || c === 'S' || c === 'N';
const SOLID = 'GSNB?MUXPh';        // what stops a body from every side
const HURTS = '^';                   // what hurts to touch
const DECOR = { c: 127, p: 126, m: 129, s: 125, f: 105, a: 85, k: 86, t: 124 };     // behind the player, touching nothing
const PLAIN = { B: 6, '?': 10, M: 10, U: 29, X: 26, '^': 68, w: 33, W: 53, P: 107, '|': 131, K: 86, k: 86 };
const cloudTile = (l, r) => (!l && !r) ? 156 : !l ? 153 : !r ? 155 : 154;

// ---- a level is a grid of letters and a list of creatures
const mkLevel = (w, h, meta) => {
	const g = [];
	for (let y = 0; y < h; y++) g.push(new Array(w).fill(' '));
	const L = { w, h, g, en: [], meta };
	L.set = (x, y, c) => { if (x >= 0 && x < w && y >= 0 && y < h) g[h - 1 - y][x] = c; };
	L.get = (x, y) => (x < 0 || x >= w || y < 0 || y >= h) ? ' ' : g[h - 1 - y][x];
	L.fill = (x0, x1, y0, y1, c) => { for (let y = y0; y <= y1; y++) for (let x = x0; x < x1; x++) L.set(x, y, c); };
	L.ground = (x0, x1, top, c = 'G') => L.fill(x0, x1, 0, top, c);
	L.water = (x0, x1, top = 1) => { L.fill(x0, x1, 0, top - 1, 'W'); L.fill(x0, x1, top, top, 'w'); };
	L.row = (x, y, s) => { for (let i = 0; i < s.length; i++) if (s[i] !== ' ') L.set(x + i, y, s[i]); };
	L.coins = (x, y, n, dx = 1, dy = 0) => { for (let i = 0; i < n; i++) L.set(x + i * dx, y + i * dy, '$'); };
	L.arc = (x, y, n, rise = 1.5) => { for (let i = 0; i < n; i++) L.set(x + i, Math.round(y + Math.sin(i / (n - 1) * Math.PI) * rise), '$'); };
	L.enemy = (t, x, y, o) => L.en.push(Object.assign({ t, x, y }, o || {}));
	L.flag = (x, y) => { for (let k = 0; k < 7; k++) L.set(x, y + k, k === 6 ? 'F' : '|'); };
	L.decor = (x, y, c) => L.set(x, y, c);
	return L;
};

// ---- level one: the meadow
const level1 = () => {
	const L = mkLevel(180, 17, { name: 'MEADOW RUN', theme: 0, music: 'level1', spawn: [2, 3.2], goal: 170 });
	L.ground(0, 32, 2); L.decor(6, 3, 's'); L.decor(9, 3, 'a'); L.decor(20, 3, 'm');
	L.coins(10, 4, 4); L.row(14, 6, 'B?B?B'); L.set(16, 6, 'M'); L.coins(15, 8, 3);
	L.enemy('slime', 24, 3);
	L.water(32, 36); L.arc(32, 4, 4, 2);
	L.ground(36, 50, 2); L.enemy('slime', 41, 3); L.enemy('slime', 45, 3); L.decor(48, 3, 'p');
	L.ground(50, 56, 4); L.ground(56, 62, 6); L.coins(57, 8, 4);
	L.ground(62, 80, 2); L.row(64, 6, 'BBB'); L.row(68, 7, '?'); L.row(71, 6, 'B?B'); L.coins(69, 9, 3);
	L.enemy('slime', 66, 3); L.enemy('slime', 72, 3); L.enemy('slime', 76, 3); L.decor(79, 3, 'k'); L.set(79, 3, 'K');
	L.water(80, 85); L.row(81, 5, 'BBB'); L.arc(80, 6, 5, 2);
	L.ground(85, 100, 2); L.fill(90, 93, 3, 3, 'X'); L.fill(91, 93, 4, 4, 'X'); L.set(92, 5, 'X'); L.coins(90, 7, 3);
	L.enemy('slime', 87, 3); L.enemy('frog', 96, 3); L.decor(98, 3, 'c');
	L.ground(100, 106, 5); L.ground(106, 112, 3); L.ground(112, 118, 5); L.coins(101, 7, 5); L.coins(113, 7, 5); L.set(109, 4, 'P'); L.coins(108, 10, 3);
	L.enemy('slime', 108, 4); L.enemy('bat', 110, 8, { range: 4 });
	L.water(118, 123); L.row(119, 6, 'CCC'); L.coins(119, 8, 3);
	L.ground(123, 150, 2); L.row(126, 6, '?B?'); L.set(127, 6, 'M'); L.row(131, 8, 'BBBBB'); L.coins(131, 10, 5);
	L.enemy('slime', 128, 3); L.enemy('slime', 133, 3); L.enemy('frog', 138, 3); L.enemy('bat', 142, 7, { range: 5 }); L.enemy('slime', 146, 3); L.decor(148, 3, 'p'); L.decor(124, 3, 'k');
	L.set(139, 3, '^'); L.set(140, 3, '^'); L.set(141, 3, '^');
	L.ground(150, 180, 2); L.fill(152, 154, 3, 3, 'X'); L.fill(154, 156, 3, 4, 'X'); L.fill(156, 158, 3, 5, 'X'); L.fill(158, 160, 3, 6, 'X'); L.coins(153, 5, 3);
	L.enemy('slime', 162, 3); L.enemy('slime', 165, 3); L.flag(170, 3); L.decor(168, 3, 'a');
	return L;
};

// ---- level two: the canyon
const level2 = () => {
	const L = mkLevel(200, 17, { name: 'SUNSET CANYON', theme: 1, music: 'level2', spawn: [2, 3.2], goal: 190 });
	L.ground(0, 24, 2, 'S'); L.decor(5, 3, 'c'); L.decor(8, 3, 'a'); L.coins(10, 4, 5); L.row(13, 6, '?B?'); L.set(14, 6, 'M');
	L.enemy('spiker', 18, 3);
	L.ground(24, 30, 4, 'S'); L.ground(30, 36, 6, 'S'); L.coins(31, 8, 4);
	L.ground(36, 40, 3, 'S'); L.set(37, 4, '^'); L.set(38, 4, '^'); L.enemy('bat', 42, 8, { range: 4 });
	L.ground(44, 62, 2, 'S'); L.coins(46, 4, 3); L.enemy('slime', 48, 3); L.enemy('spiker', 54, 3); L.enemy('frog', 58, 3); L.decor(60, 3, 'c');
	L.row(48, 6, 'BBBB'); L.row(52, 7, '?'); L.coins(48, 8, 4);
	L.ground(66, 70, 5, 'S'); L.ground(74, 78, 7, 'S'); L.ground(82, 86, 5, 'S'); L.arc(70, 8, 4, 2); L.arc(78, 10, 4, 2); L.decor(67, 6, 'k'); L.set(67, 6, 'K');
	L.enemy('bat', 72, 10, { range: 3 }); L.enemy('bat', 80, 9, { range: 3 });
	L.ground(88, 112, 2, 'S'); L.row(92, 7, 'B?B'); L.coins(92, 9, 3);
	for (let x = 96; x < 104; x += 2) L.set(x, 3, '^');
	L.set(100, 3, ' '); L.row(98, 6, 'CCCC'); L.coins(98, 8, 4);
	L.enemy('spiker', 91, 3); L.enemy('frog', 107, 3); L.enemy('slime', 109, 3); L.decor(110, 3, 'p');
	L.ground(116, 122, 3, 'S'); L.set(119, 4, 'P'); L.coins(118, 9, 3);
	L.ground(122, 134, 8, 'S'); L.fill(124, 134, 3, 7, ' '); L.ground(124, 126, 3, 'S');
	L.ground(126, 150, 2, 'S'); L.row(130, 6, '?M?'); L.row(134, 9, 'BBBBB'); L.coins(134, 11, 5);
	L.enemy('spiker', 133, 3); L.enemy('spiker', 138, 3); L.enemy('frog', 142, 3); L.enemy('bat', 144, 8, { range: 5 }); L.decor(147, 3, 'c'); L.decor(129, 3, 'k'); L.set(129, 3, 'K');
	L.set(140, 3, '^'); L.set(141, 3, '^');
	L.ground(154, 158, 4, 'S'); L.ground(162, 166, 6, 'S'); L.ground(170, 174, 4, 'S'); L.arc(158, 7, 4, 2); L.arc(166, 9, 4, 2);
	L.enemy('bat', 160, 9, { range: 3 }); L.enemy('bat', 168, 9, { range: 3 });
	L.ground(176, 200, 2, 'S'); L.row(180, 6, 'B?BMB'); L.coins(181, 8, 4); L.enemy('spiker', 183, 3); L.enemy('slime', 186, 3);
	L.flag(190, 3); L.decor(188, 3, 'a');
	return L;
};

// ---- level three: the frozen heights. Taller, with clouds to climb and ice underfoot.
const level3 = () => {
	const L = mkLevel(210, 24, { name: 'FROZEN HEIGHTS', theme: 0, music: 'level3', spawn: [2, 3.2], goal: 200, snow: true });
	L.ground(0, 22, 2, 'N'); L.decor(6, 3, 'p'); L.decor(9, 3, 'a'); L.coins(12, 4, 4); L.row(16, 6, '?B?'); L.enemy('slime', 19, 3);
	L.ground(22, 28, 4, 'N'); L.ground(28, 34, 6, 'N'); L.ground(34, 40, 8, 'N'); L.coins(35, 10, 4); L.decor(37, 9, 'p');
	L.row(42, 8, 'CCC'); L.row(47, 10, 'CCC'); L.row(52, 12, 'CCC'); L.row(57, 10, 'CCC'); L.coins(43, 10, 2); L.coins(48, 12, 2); L.coins(53, 14, 2); L.coins(58, 12, 2);
	L.enemy('bat', 50, 9, { range: 4 }); L.enemy('bat', 55, 13, { range: 4 });
	L.ground(62, 80, 8, 'N'); L.fill(62, 80, 3, 7, ' '); L.ground(62, 66, 5, 'N');
	L.ground(66, 90, 4, 'N'); L.row(68, 8, 'B?B'); L.row(72, 8, 'M'); L.coins(70, 10, 5);
	L.enemy('thwomp', 76, 9); L.enemy('slime', 82, 5); L.enemy('spiker', 86, 5); L.decor(88, 5, 'k'); L.set(88, 5, 'K');
	L.water(90, 96, 1); L.row(91, 6, 'CCCC'); L.coins(91, 8, 4);
	L.ground(96, 110, 3, 'N'); L.enemy('mine', 100, 6); L.enemy('mine', 104, 8); L.enemy('slime', 107, 4); L.row(98, 7, '?B?'); L.coins(99, 9, 3);
	L.ground(110, 116, 6, 'N'); L.ground(116, 122, 9, 'N'); L.ground(122, 128, 12, 'N'); L.coins(117, 11, 4); L.coins(123, 14, 4);
	L.set(119, 10, 'P'); L.enemy('bat', 126, 15, { range: 3 });
	L.row(130, 12, 'CCCC'); L.row(136, 11, 'CCCC'); L.row(142, 10, 'CCCC'); L.row(148, 9, 'CCCC'); L.arc(130, 14, 5, 1.5); L.arc(148, 11, 4, 1.5);
	L.enemy('bat', 134, 14, { range: 4 }); L.enemy('bat', 144, 12, { range: 4 }); L.enemy('mine', 139, 9);
	L.ground(154, 176, 4, 'N'); L.enemy('thwomp', 160, 9); L.enemy('thwomp', 167, 9); L.enemy('spiker', 172, 5); L.row(158, 8, '?B?'); L.set(159, 8, 'M'); L.decor(156, 5, 'k'); L.set(156, 5, 'K');
	L.set(163, 5, '^'); L.set(164, 5, '^');
	L.ground(176, 182, 2, 'N'); L.water(182, 188, 1); L.row(183, 5, 'CCCC'); L.coins(183, 7, 4);
	L.ground(188, 210, 2, 'N'); L.enemy('slime', 192, 3); L.enemy('slime', 195, 3); L.enemy('spiker', 197, 3);
	L.flag(200, 3); L.decor(198, 3, 'a');
	return L;
};

// ---- the keep: a room, a ceiling and a boss
const levelBoss = () => {
	const L = mkLevel(44, 17, { name: 'ROBOT KEEP', theme: 2, music: 'boss', spawn: [5, 3.2], boss: true, goal: -1 });
	L.ground(0, 44, 2, 'N');
	L.fill(0, 2, 3, 16, 'N'); L.fill(42, 44, 3, 16, 'N'); L.fill(0, 44, 15, 16, 'N');
	L.row(8, 6, 'CCCC'); L.row(32, 6, 'CCCC'); L.row(19, 9, 'CCCCCC');
	L.set(14, 3, 'P'); L.set(29, 3, 'P');
	L.enemy('boss', 34, 3);
	return L;
};

// ---- the map the player walks between levels (a level of its own, with no danger in it)
const OVER = {
	w: 34, h: 17,
	nodes: [{ x: 5.5, y: 4, label: 1 }, { x: 13, y: 6, label: 2 }, { x: 21, y: 5, label: 3 }, { x: 26, y: 7, label: 4 }],
	tops: [[0, 11, 4], [11, 15, 6], [15, 24, 5], [24, 28, 7], [28, 34, 6]]
};
const overworld = () => {
	const L = mkLevel(OVER.w, OVER.h, { name: 'WORLD', theme: 0, music: 'overworld', spawn: [5.5, 5.5] });
	for (const [a, b, t] of OVER.tops) L.ground(a, b, t - 1);
	L.decor(2, 4, 'p'); L.decor(8, 4, 'c'); L.decor(10, 4, 'f'); L.decor(12, 6, 's'); L.decor(14, 6, 'm'); L.decor(17, 5, 'p'); L.decor(19, 5, 'c'); L.decor(23, 5, 's'); L.decor(26, 7, 'p'); L.decor(30, 6, 'c'); L.decor(32, 6, 'p'); L.decor(3, 4, 's');
	return L;
};
const LEVELS = [level1, level2, level3, levelBoss];
const NAMES = ['MEADOW RUN', 'SUNSET CANYON', 'FROZEN HEIGHTS', 'ROBOT KEEP'];

// ---- the creatures: size of the body, in tiles, and how it is drawn
const KINDS = {
	slime: { w: 0.7, h: 0.6, frames: [18, 19], dead: 20, speed: 1.5, stomp: true },
	spiker: { w: 0.7, h: 0.8, frames: [15, 16], dead: 17, speed: 1.1, stomp: false },
	frog: { w: 0.6, h: 0.75, frames: [13, 14], dead: 14, speed: 3.2, stomp: true },
	bat: { w: 0.7, h: 0.5, frames: [24, 25, 26, 25], dead: 25, speed: 2.0, stomp: true },
	thwomp: { w: 1.1, h: 1.1, frames: [11, 12], dead: 12, speed: 0, stomp: false },
	mine: { w: 0.8, h: 0.8, frames: [8], dead: 8, speed: 0, stomp: false },
	boss: { w: 2.4, h: 2.2, frames: [21, 22, 23], dead: 23, speed: 2.4, stomp: true, scale: 2.2 }
};

// which tile of the tile sheet draws the letter at (x, y), and how far back or forward it sits; null for what is drawn some other way (coins, the flag)
const tileOf = (get, w, h, x, y) => {
	const c = get(x, y);
	if (c === ' ' || c === '$' || c === 'F') return null;
	const T = (xx, yy) => (yy < 0) || ((xx < 0 || xx >= w) && yy < h) || isTerrain(get(xx, yy));
	if (isTerrain(c)) {
		const u = T(x, y + 1), d = T(x, y - 1), l = T(x - 1, y), r = T(x + 1, y);
		const col = (!l && !r) ? 0 : !l ? 1 : !r ? 3 : 2;
		return { idx: u ? (d ? 120 : 140) + col : TOPS[c][d ? 1 : 0] + col, z: 0 };
	}
	if (c === 'C') return { idx: cloudTile(get(x - 1, y) === 'C', get(x + 1, y) === 'C'), z: 0 };
	if (DECOR[c]) return { idx: DECOR[c], z: -0.3 };
	if (PLAIN[c] != null) return { idx: PLAIN[c], z: (c === '^' || c === 'w' || c === 'W') ? 0.05 : c === '|' ? -0.1 : 0 };
	return null;
};

// Shared by every section: reading the level, moving a body through it, and the small things done to the document.

const copy = o => JSON.parse(JSON.stringify(o));
const cellAt = (x, y) => {
	const lv = X.lv;
	if (x < 0 || x >= lv.w) return 'G';            // the sides of a level are walls
	if (y < 0 || y >= lv.h) return ' ';            // under it is a pit; over it is air
	return lv.rows[lv.h - 1 - y][x];
};
const setCell = (x, y, c) => {
	const lv = X.lv;
	if (x < 0 || x >= lv.w || y < 0 || y >= lv.h) return;
	const r = lv.h - 1 - y, row = lv.rows[r];
	if (row[x] === c) return;
	lv.rows[r] = row.slice(0, x) + c + row.slice(x + 1);
	X.tilesDirty = true;
};
const isSolid = (cx, cy) => SOLID.indexOf(cellAt(cx, cy)) >= 0;

// A body is { x (middle), y (feet), w, h, vx, vy }. Moves it by (dx, dy), stopping it at solid cells, one axis at a time.
// Returns which sides it was stopped on, and the cells whose underside it struck.
const moveBody = (b, dx, dy, passClouds) => {
	const f = { l: false, r: false, u: false, d: false, bump: [], on: ' ' };
	// a spring is a floor for the player and nothing in the way of anything else
	const solid = (cx, cy) => (b.noP && cellAt(cx, cy) === 'P') ? false : isSolid(cx, cy);
	if (dx !== 0) {
		b.x += dx;
		const y0 = Math.floor(b.y + 0.002), y1 = Math.floor(b.y + b.h - 0.002);
		const cx = Math.floor(dx > 0 ? b.x + b.w / 2 : b.x - b.w / 2);
		for (let cy = y0; cy <= y1; cy++) {
			if (solid(cx, cy)) {
				if (dx > 0) { b.x = cx - b.w / 2 - 0.0005; f.r = true; } else { b.x = cx + 1 + b.w / 2 + 0.0005; f.l = true; }
				break;
			}
