	setTxt('hud.coins', hudOn ? 'x ' + String(g.coins).padStart(2, '0') : ''); placed('hud.coins', [left + 1.1, top - 1.1, 0]);
	setTxt('hud.lives', hudOn ? 'x ' + g.lives : ''); placed('hud.lives', [left + 5.35, top - 1.1, 0]);
	setTxt('hud.score', hudOn || mode === 'map' ? 'SCORE ' + String(g.score).padStart(6, '0') : ''); placed('hud.score', [right, top + 0.05, 0]);
	// the boss's strength
	const boss = dy => dy.en.find(e => e.t === 'boss');
	const bz = inPlay ? boss(X.dy) : null;
	show('hud.bossBar', !!bz && bz.s !== 'enter');
	if (bz) {
		placed('hud.bossBar', [0, -halfH + 0.8, 0]);
		const f = clamp(bz.hp / 6, 0.001, 1);
		placed('hud.bossBar.fill', [-4 + 4 * f, 0, 0.01], [f, 1, 1]);
		setTxt('hud.bossBar.name', 'ROBOT');
	}
	// the level's name, for the first few seconds
	const banner = hudOn && g.mt < 3.2 && mode === 'play' && !g.paused && !(g.p && g.p.dead);
	setTxt('hud.level', banner ? lvName : ''); placed('hud.level', [0, top - 2.4, 0]);
	setTxt('hud.levelNo', banner ? 'COURSE ' + (g.level + 1) : ''); placed('hud.levelNo', [0, top - 1.5, 0]);

	// the big words
	let msg = '', sub = '', sub2 = '', dim = false;
	const blink = (g.t * 2 | 0) % 2 === 0;
	if (mode === 'title') {
		msg = 'PIXEL QUEST'; dim = false;
		sub = blink ? (g.gest ? 'PRESS ENTER' : 'PRESS ANY KEY') : '';
		sub2 = X.saved ? 'N  NEW GAME' : 'ARROWS  RUN    SPACE  JUMP';
	} else if (mode === 'map') {
		const n = g.node;
		msg = ''; sub = (n === 3 && g.unlocked < 3 ? '' : NAMES[n]) + (g.done[n] ? '  CLEARED' : ''); sub2 = 'ARROWS  WALK     ENTER  PLAY';
	} else if (mode === 'play' && g.paused) { msg = 'PAUSED'; sub = 'ESC  RESUME'; sub2 = 'N  LEAVE THE LEVEL'; dim = true; }
	else if (mode === 'clear') { msg = X.lv.meta.boss ? 'THE ROBOT IS DOWN!' : 'COURSE CLEAR!'; sub = 'COINS ' + g.coins + '    SCORE ' + g.score; dim = false; }
	else if (mode === 'gameover') { msg = 'GAME OVER'; dim = true; }
	else if (mode === 'win') { msg = 'YOU WIN!'; sub = 'THE KEEP IS QUIET AT LAST'; sub2 = g.mt > 2 ? 'PRESS ENTER' : ''; dim = true; }
	setTxt('hud.msg', msg); placed('hud.msg', [0, mode === 'title' ? 4.2 : 1.2, 0]);
	setTxt('hud.sub', sub); placed('hud.sub', [0, mode === 'title' ? -2.6 : mode === 'map' ? halfH - 1.8 : -0.6, 0]);
	setTxt('hud.sub2', sub2); placed('hud.sub2', [0, mode === 'title' ? -4.1 : mode === 'map' ? -halfH + 1.2 : -1.8, 0]);
	setTxt('hud.credit', mode === 'title' ? 'MUSIC  KEVIN MACLEOD  CC BY 4.0      ART  KENNEY  CC0' : ''); placed('hud.credit', [0, -halfH + 0.55, 0]);
	show('hud.dim', dim);
	const a = Math.min(0.3, (g.mt || 0) * 0.8);
	setTint('hud.dim.panel', [0, 0, 0, dim ? a : 0]);
}

}
