// ---- audio.js
{
// Sound: one tune at a time for wherever the player is, and the short sounds that were asked for this frame.
// A tune is asked for once, when it changes; if it is not heard to be playing a moment later (the browser had not yet let sound begin,
// or the file had not yet been read) it is asked for again, never every frame.
const g = X.g;
const clipState = name => { const n = get('audio.' + name); return n && n.utilities && n.utilities.clip ? n.utilities.clip.properties.state : null; };
let want = '';
if (g.mode === 'title' || g.mode === 'win') want = 'title';
else if (g.mode === 'map') want = 'overworld';
else if (g.mode === 'play' && g.where !== 'over' && g.p && !g.p.dead) want = X.lv.meta.music;
const names = ['title', 'overworld', 'level1', 'level2', 'level3', 'boss'];
if (g.mus !== want) {
	for (const n of names) {
		if (n === want) continue;
		const s = clipState('m_' + n);
		if (s && (s.playing || g.mus === n)) comp('audio.m_' + n, 'clip', { stop: true });
	}
	g.mus = want;
	g.musT = g.t - 10;
}
if (want) {
	const s = clipState('m_' + want);
	if (X.display.gesture && s && s.loaded && !s.playing && g.t - g.musT > 1.0) {
		comp('audio.m_' + want, 'clip', { play: true });
		g.musT = g.t;
	}
}
const seen = {};
for (const name of X.sfx) { if (seen[name]) continue; seen[name] = 1; comp('audio.s_' + name, 'clip', { play: true }); }

}
mergeInto(S, patch);

// ---- final.js
{
// The end of a frame: what changed is written back.
const g = X.g;
if (X.tilesDirty) emitTiles();
const gs = JSON.stringify(g);
if (gs !== X.g0) {
	const out = JSON.parse(gs);
	// keys that were taken away are told to the document as nulls
	const before = JSON.parse(X.g0);
	for (const k of Object.keys(before)) if (!(k in out)) out[k] = null;
	put('game', out);
}
if (X.lvNew) put('lvl', X.lv);
else if (JSON.stringify(X.lv.rows) !== X.lv0) put('lvl', { rows: X.lv.rows });
const ds = JSON.stringify(X.dy);
if (ds !== X.d0) put('dyn', X.dy);
if (X.saveWrite !== undefined) {
	const st = get('save').utilities.disk.properties.state;
	comp('save', 'disk', { value: X.saveWrite, revision: ((st && st.revision) || 0) + 1 });
}

}
mergeInto(S, patch);

return done();
